# We'll call next_song repeatedly until we hit a downloaded song
downloaded_ids = {song['song_id'] for song in downloaded}
current_song_id = None
for _ in range(len(queue) + 1):  # safety limit
    result = apis.spotify.next_song(access_token=access_token)
    print("Next song result:", result)
    if 'song_id' in result:
        current_song_id = result['song_id']
        if current_song_id in downloaded_ids:
            print(f"Reached downloaded song with ID {current_song_id}")
            break
    else:
        print("Error:", result)
        break
else:
    print("No downloaded song found in queue cycle")

