# Now get all current venmo friends (paginate through all pages)
venmo_friends = []
page_index = 0
while True:
    result = apis.venmo.search_friends(
        access_token=venmo_login['access_token'],
        page_index=page_index,
        page_limit=20
    )
    if isinstance(result, dict) and 'message' in result:
        break
    if not result:
        break
    venmo_friends.extend(result)
    if len(result) < 20:
        break
    page_index += 1

print("Venmo friends count:", len(venmo_friends))
for f in venmo_friends:
    print(f)

