steps.code:
# Get details for all unique song IDs
song_details = {}
for song_id in sorted(all_song_ids):
    result = apis.spotify.show_song(song_id=song_id, access_token=spotify_token)
    song_details[song_id] = result
    print(f"Song {song_id}: {result['title']} by {[a['name'] for a in result['artists']]}")

# Match old songs to song IDs based on title and artist names
old_song_ids = []
for old in old_songs:
    matches = []
    for sid, details in song_details.items():
        if details['title'] == old['title']:
            # Compare artist names as sets
            detail_artists = {a['name'] for a in details['artists']}
            old_artists = set(old['artists'])
            if detail_artists == old_artists:
                matches.append(sid)
    if len(matches) == 1:
        old_song_ids.append(matches[0])
        print(f"Matched: {old['title']} -> song_id {matches[0]}")
    elif len(matches) > 1:
        print(f"Multiple matches for {old['title']}: {matches}")
    else:
        print(f"No match for {old['title']}")

print(f"\nTotal matched old songs: {len(old_song_ids)}")
print(old_song_ids)

