# Let's check the current state of each playlist to see which matched songs still remain
# We'll iterate over all playlists and remove any matched songs that are still present

for playlist in all_playlists:
    pid = playlist['playlist_id']
    # Get current playlist details
    current = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    current_song_ids = [song['id'] for song in current['songs']]
    # Find matched songs still in this playlist
    to_remove = [sid for sid in current_song_ids if sid in matched_song_ids]
    if to_remove:
        print(f"Playlist {pid} ({playlist['title']}) still has matched songs: {to_remove}")
        for sid in to_remove:
            try:
                result = apis.spotify.remove_song_from_playlist(
                    playlist_id=pid,
                    song_id=sid,
                    access_token=spotify_token
                )
                print(f"  Removed {sid}: {result}")
            except Exception as e:
                print(f"  Error removing {sid}: {e}")
    else:
        print(f"Playlist {pid} ({playlist['title']}) has no matched songs remaining.")

# Remove matched songs from all playlists and add them to the new playlist
new_playlist_id = 654
added_songs = set()

for playlist_id, song_ids in playlist_songs.items():
    for song_id in song_ids:
        if song_id in matched_song_ids:
            # Remove from original playlist
            apis.spotify.remove_song_from_playlist(playlist_id=playlist_id, song_id=song_id, access_token=spotify_token)
            # Add to new playlist if not already added
            if song_id not in added_songs:
                apis.spotify.add_song_to_playlist(playlist_id=new_playlist_id, song_id=song_id, access_token=spotify_token)
                added_songs.add(song_id)

print("Removed and added", len(added_songs), "unique songs")

