steps.code:
# Search for each song to get its song_id
song_ids = {}
for title, artist in songs_to_archive:
    # Search with the title as query
    results = apis.spotify.search_songs(query=title, access_token=spotify_token, page_limit=20)
    # Find the song that matches both title and artist
    found = None
    for song in results:
        if song['title'].lower() == title.lower():
            # Check if any artist matches
            for art in song['artists']:
                if art['name'].lower() == artist.lower():
                    found = song
                    break
            if found:
                break
    if found:
        song_ids[title] = found['song_id']
        print(f"Found: {title} by {artist} -> song_id={found['song_id']}")
    else:
        print(f"NOT FOUND: {title} by {artist}")

print(f"\nTotal found: {len(song_ids)}")

