# Let's get the details of each playlist to see its songs
playlist_details = {}
for p in playlists:
    pl = apis.spotify.show_playlist(playlist_id=p['playlist_id'], access_token=spotify_login['access_token'])
    playlist_details[p['playlist_id']] = pl
    print(f"Playlist {p['playlist_id']} ({p['title']}): {len(pl['songs'])} songs")
    # Print first few songs for inspection
    for s in pl['songs'][:3]:
        print(f"  Song ID {s['id']}: {s['title']} (artists: {s['artist_ids']})")

# Let's find the song IDs for each song in songs_to_archive
song_id_map = {}  # (title, artist) -> song_id
for title, artist in songs_to_archive:
    # Search for the song by title
    results = apis.spotify.search_songs(query=title, access_token=spotify_token)
    found = None
    for song in results:
        if song['title'].lower() == title.lower():
            # Check if any artist matches
            for art in song['artists']:
                if art['name'].lower() == artist.lower():
                    found = song['song_id']
                    break
            if found:
                break
    if found:
        song_id_map[(title, artist)] = found
        print(f"Found: {title} by {artist} -> song_id {found}")
    else:
        print(f"NOT FOUND: {title} by {artist}")

print(f"\nTotal songs mapped: {len(song_id_map)}")

