# Search for each song in the archive list and collect their song IDs
archive_song_ids = []
for title, artist in songs_to_archive:
    # Search for the song by title
    search_results = apis.spotify.search_songs(query=title, access_token=login_result["access_token"])
    # Find the song that matches both title and artist
    found = False
    for song in search_results:
        if song["title"] == title:
            # Check if any artist matches
            for art in song["artists"]:
                if art["name"] == artist:
                    archive_song_ids.append(song["song_id"])
                    found = True
                    break
        if found:
            break
    if not found:
        print(f"Song not found: {title} by {artist}")

print("Archive song IDs:", archive_song_ids)

# Search for each archived song to get its song_id
archived_song_ids = []
for title, artist in archived_songs:
    # Search by title
    results = apis.spotify.search_songs(query=title, access_token=login_result["access_token"], page_limit=20)
    # Find the song that matches the artist
    found = None
    for song in results:
        # Check if any artist matches
        for art in song.get("artists", []):
            if art["name"].lower() == artist.lower():
                found = song
                break
        if found:
            break
    if found:
        archived_song_ids.append(found["song_id"])
        print(f"Found: {title} by {artist} -> song_id={found['song_id']}")
    else:
        print(f"NOT FOUND: {title} by {artist}")

print("Archived song IDs:", archived_song_ids)

