# Let's write a function to find the exact song_id for each old song.
def find_song_id(title, artists, access_token):
    # Build query: title + artist names
    query = title
    for artist in artists:
        query += ' ' + artist
    # Search with max page limit
    page_index = 0
    page_limit = 20
    while True:
        results = apis.spotify.search_songs(
            query=query,
            access_token=access_token,
            page_index=page_index,
            page_limit=page_limit
        )
        if not results:
            return None
        for song in results:
            if song['title'].lower() == title.lower():
                # Check artists match
                song_artists = {a['name'].lower() for a in song['artists']}
                expected_artists = {a.lower() for a in artists}
                if song_artists == expected_artists:
                    return song['song_id']
        # If we got fewer than page_limit results, no more pages
        if len(results) < page_limit:
            return None
        page_index += 1

# Test with first song
