# Define the set of song IDs to archive
songs_to_archive_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}
print("Songs to archive IDs:", songs_to_archive_ids)

# Check which playlists contain these songs
for pl in playlists:
    pl_id = pl['playlist_id']
    pl_songs = pl['song_ids']
    common = set(pl_songs) & songs_to_archive_ids
    if common:
        print(f"Playlist {pl_id} ({pl['title']}) contains songs to archive: {common}")

