# Let's write a function to find the correct song for each TODO entry
import re

def find_song_release_date(title, artists, token):
    # Search for the song
    results = apis.spotify.search_songs(query=title, access_token=token, page_limit=20)
    # Filter results: exact title match and all artists match
    for song in results:
        if song['title'].lower() == title.lower():
            song_artists = {a['name'].lower() for a in song['artists']}
            note_artists = {a.lower() for a in artists}
            if song_artists == note_artists:
                # Found exact match
                release_date = song['release_date']  # e.g., "2021-03-23T13:53:26"
                # Extract month and year
                match = re.match(r'(\d{4})-(\d{2})-\d{2}', release_date)
                if match:
                    year = match.group(1)
                    month = match.group(2)
                    return f"{month}/{year}"
    return None

# Test for the first TODO song
release = find_song_release_date(todo_songs[0]['title'], todo_songs[0]['artists'], spotify_token)
print(release)

# Process all TODO songs and collect release dates
release_dates = {}
for song_info in todo_songs:
    title = song_info['title']
    artists = song_info['artists']
    release = find_song_release_date(title, artists, spotify_token)
    if release:
        release_dates[song_info['line']] = release
        print(f"{title} -> {release}")
    else:
        print(f"NO MATCH for {title}")

