# Fetch all liked songs properly (the API returns a list directly)
liked_songs = []
page_index = 0
while True:
    result = apis.spotify.show_liked_songs(access_token=spotify_token, page_index=page_index, page_limit=20)
    if isinstance(result, list):
        liked_songs.extend(result)
        if len(result) < 20:
            break
        page_index += 1
    else:
        print("Error:", result)
        break
print(f"Total liked songs: {len(liked_songs)}")
for song in liked_songs:
    print(song)

